DECLARE
    v_count INTEGER;
BEGIN
    UPDATE control_interno.auditoria
    SET actividad_plan_anual_id = p_actividad_id
    WHERE activa = true
      AND archivada = false
      AND control_interno.fn_auditoria_en_programa_anual(plan_anual_vigencia, fecha_inicio, p_año);

    GET DIAGNOSTICS v_count = ROW_COUNT;
