    -- Update drafts_count
    UPDATE disciplinary_processes
    SET drafts_count = (
        SELECT COUNT(*)
        FROM legal_autos
        WHERE "processId" = NEW."processId"
        AND estado = 'BORRADOR'
    )
    WHERE id = NEW."processId";

    RETURN NEW;
END;

