BEGIN
    IF NEW.numero_interno IS NULL OR NEW.numero_interno = '' THEN
        NEW.numero_interno := 'HAL-ESAP-' || EXTRACT(YEAR FROM CURRENT_DATE) || '-' || 
                              LPAD(nextval('seq_hallazgo_interno')::TEXT, 4, '0');
    END IF;
    RETURN NEW;
END;

BEGIN
    IF TG_OP = 'UPDATE' AND OLD.estado != NEW.estado THEN
        INSERT INTO historial_requerimientos (requerimiento_id, accion, descripcion, estado_anterior, estado_nuevo)
        VALUES (NEW.id, 'CAMBIO_ESTADO', 'Cambio de estado automático', OLD.estado, NEW.estado);
    END IF;
    RETURN NEW;
END;

BEGIN
    IF OLD.cerrada_en IS NOT NULL AND NOT travel_expenses.fn_purga_pruebas_activa() THEN
        RAISE EXCEPTION 'EFDS-1310: la legalización % está cerrada (%); su expediente es inmutable.',
            OLD.id, OLD.cerrada_en
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END

BEGIN
    IF travel_expenses.fn_purga_pruebas_activa() THEN
        RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'EFDS-1310: las solicitudes de reversión no se borran.'
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.estado <> 'PENDIENTE' THEN
        RAISE EXCEPTION 'EFDS-1310: la solicitud de reversión % ya fue resuelta (%); es inmutable.', OLD.id, OLD.estado
            USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW.legalizacion_id, NEW.motivo, NEW.solicitada_por_id, NEW.solicitada_en)
       IS DISTINCT FROM (OLD.legalizacion_id, OLD.motivo, OLD.solicitada_por_id, OLD.solicitada_en) THEN
        RAISE EXCEPTION 'EFDS-1310: de una solicitud de reversión solo se registra su resolución.'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    IF NOT travel_expenses.fn_purga_pruebas_activa() THEN
        RAISE EXCEPTION 'EFDS-1310: el historial de revisión de legalizaciones es de solo inserción.'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
END

DECLARE
    v_legalizacion UUID := CASE WHEN TG_OP = 'INSERT' THEN NEW.legalizacion_id ELSE OLD.legalizacion_id END;
    v_cerrada      TIMESTAMPTZ;
BEGIN
    SELECT cerrada_en INTO v_cerrada
      FROM travel_expenses.legalizaciones_comision WHERE id = v_legalizacion;
    IF v_cerrada IS NOT NULL AND NOT travel_expenses.fn_purga_pruebas_activa() THEN
        RAISE EXCEPTION 'EFDS-1310: la legalización % está cerrada; sus soportes son inmutables.', v_legalizacion
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END

